using System;
using System.Text;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.EventSystems;
using TMPro;
using DG.Tweening;
using LWS.TruckHockey;
using LWS.TruckSports;
namespace LWS.TruckAirHockey {
public enum AirHockeyScreen {Setup,Join,Play,Pause,Help,Settings,Confirm,Disconnect,Result}
public sealed class AirHockeyMenus:SportsMenuView {
 public AirHockeyPresentation presentation;
 public AirHockeyMatch match;public AirHockeyScreen Screen;public TMP_InputField[] names;public TMP_Text[] sourceLabels,levelLabels,colorLabels;public TMP_Text modeLabel,joinText,disconnectText,scoreText,serveText,noticeText,resultText,confirmText;public GameObject hud;public RectTransform resultTitle;
 public Color[] palette={new Color(.15f,.8f,1),new Color(1,.55f,.13f),new Color(.85f,.25f,.7f),new Color(.6f,1,.3f),new Color(.9f,.85f,.25f)};
 int revision=-1,gateFrame;bool released;float nextHud;string pending;AirHockeyScreen previous;SportsMenuAction[][] cached;Tween celebration;
 public const string Rules="FIRST TO 7 • 1v1 • Your truck IS the mallet.\n\nDrive forward, steer and brake/reverse relative to your truck. Strike the puck physically; no shoot button. Trucks stay in their own half and outside goals. The puck crosses center freely and rebounds from rails. No possession or aiming assist.\n\nWhole puck crossing inside the opening scores for the opponent of that goal, including own goals. The conceding player serves after a brief countdown. Opening serve alternates on rematches. Escaped or genuinely trapped pucks recover fairly without changing scores; a reachable stationary puck stays in play.\n\nKeyboard: Blue W/A/S/D; Orange arrows. Whole controller: left stick steer, RT forward, LT brake/reverse. Shared controller: each stick X steers / Y drives its own truck. North joins, Start/Escape pauses. Each input source has one owner. Reconnect/reassign and release controls before confirming. Mouse / arrows / D-pad / Enter / South navigate menus.";
 protected override void Start(){base.Start();cached=new SportsMenuAction[pages.Length][];for(int i=0;i<pages.Length;i++)if(pages[i]!=null)cached[i]=pages[i].GetComponentsInChildren<SportsMenuAction>(true);for(int i=0;i<2;i++){int slot=i;names[i].onEndEdit.AddListener(v=>{match.players[slot].name=string.IsNullOrWhiteSpace(v)?"Player "+(slot+1):v.Trim();match.Save();match.Dirty();});}Show(Screen);}
 public void Gate(){gateFrame=Time.frameCount;released=false;}public void Dirty(){revision=-1;}
 public void Show(AirHockeyScreen screen){Screen=screen;hud.SetActive(screen==AirHockeyScreen.Play);base.Show((int)screen);Gate();Dirty();if(screen==AirHockeyScreen.Result)resultText.text=match.players[match.rules.Winner].name+" WINS\n"+match.players[0].name+"  "+match.rules.Score[0]+" : "+match.rules.Score[1]+"  "+match.players[1].name+"\nFirst to 7 • Rematch alternates opening serve";}
 bool FreshConfirm(){if(!released)return false;if(SportsDeviceInput.KeyDown(Key.Enter)||SportsDeviceInput.KeyDown(Key.Space)||Mouse.current!=null&&Mouse.current.leftButton.wasReleasedThisFrame)return true;foreach(var p in match.players)if(p.controller&&p.pad!=null&&p.pad.added&&p.pad.enabled&&p.pad.buttonSouth.wasPressedThisFrame)return true;return match.AllAI;}
 public override void Action(string key){
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 if(Array.IndexOf(Environment.GetCommandLineArgs(),"-tsArenaUpdate")>=0)Debug.Log("AH_UI_ACTION key="+key+" screen="+Screen+" fresh="+released+" confirm="+FreshConfirm()+" frame="+Time.frameCount);
#endif
if((Screen==AirHockeyScreen.Disconnect||Screen==AirHockeyScreen.Join||Screen==AirHockeyScreen.Confirm||Screen==AirHockeyScreen.Pause||key=="rematch")&&!FreshConfirm())return;base.Action(key);if(key.StartsWith("source")){match.CycleSource(int.Parse(key.Substring(6)));return;}if(key.StartsWith("level")){int i=int.Parse(key.Substring(5));match.players[i].difficulty=(HockeyDifficulty)(((int)match.players[i].difficulty+1)%3);match.Save();match.Dirty();return;}if(key.StartsWith("color")){int i=int.Parse(key.Substring(5)),c=Array.IndexOf(palette,match.players[i].color);c=(c+1)%palette.Length;if(palette[c]==match.players[1-i].color)c=(c+1)%palette.Length;match.players[i].color=palette[c];match.Save();match.Dirty();return;}if(key.StartsWith("reassign")){match.Unassign(int.Parse(key.Substring(8)));return;}
  switch(key){case "mode":match.Configure((AirHockeyMode)(((int)match.mode+1)%6));break;case "start":match.StartMatch();break;case "resume":match.Resume();break;case "rematch":match.StartMatch(true);break;case "setup":match.ChangeSetup();break;case "help":previous=Screen;Show(AirHockeyScreen.Help);break;case "settings":previous=Screen;SettingsText();Show(AirHockeyScreen.Settings);break;case "back":Back();break;case "front":if(match.InMatch&&match.rules.Phase!=AirHockeyPhase.Finished){pending="front";confirmText.text="RETURN TO SPORT SELECTION?\nThe current match will be abandoned.";Show(AirHockeyScreen.Confirm);}else SportsNavigation.FrontEnd();break;case "restart":pending="restart";confirmText.text="RESTART MATCH?\nScores reset; participant setup is retained.";Show(AirHockeyScreen.Confirm);break;case "yes":if(pending=="restart")match.StartMatch();else SportsNavigation.FrontEnd();break;case "no":Show(AirHockeyScreen.Pause);break;}}
 public void Back(){if((Screen==AirHockeyScreen.Confirm||Screen==AirHockeyScreen.Disconnect||Screen==AirHockeyScreen.Pause)&&!released)return;if(Screen==AirHockeyScreen.Play){match.Pause();return;}if(Screen==AirHockeyScreen.Pause||Screen==AirHockeyScreen.Disconnect){if(released)match.Resume();return;}if(Screen==AirHockeyScreen.Help||Screen==AirHockeyScreen.Settings)Show(previous);else if(Screen==AirHockeyScreen.Confirm)Show(AirHockeyScreen.Pause);else if(Screen==AirHockeyScreen.Join)match.ChangeSetup();else if(Screen==AirHockeyScreen.Setup)SportsNavigation.FrontEnd();}
 void Refresh(){if(cached==null||revision==match.Revision)return;revision=match.Revision;modeLabel.text=new[]{"HUMAN vs AI","SHARED KEYBOARD","SEPARATE CONTROLLERS","KEYBOARD + CONTROLLER","AI vs AI • SPECTATE","ONE PAD • TWO STICKS","CUSTOM MIX"}[(int)match.mode];var text=new StringBuilder("North / Y / Triangle joins an empty input source.\n\n");for(int i=0;i<2;i++){var p=match.players[i];names[i].SetTextWithoutNotify(p.name);sourceLabels[i].text=p.source.ToString().ToUpper();levelLabels[i].text=p.difficulty.ToString().ToUpper();levelLabels[i].transform.parent.gameObject.SetActive(p.source==HockeySource.AI);colorLabels[i].text="COLOR";colorLabels[i].color=p.color;text.Append(p.name).Append(" • ").Append(p.source).Append(p.controller?(match.Ready(i)?" • "+p.pad.displayName:" • DISCONNECTED / NOT JOINED"):"").Append('\n');}text.Append("\n").Append(match.ValidateOwnership(out string reason)?"Whole pad = one participant; left/right sticks = separate owners.\nScores, serving side and physical state are preserved on disconnect.":reason);joinText.text=disconnectText.text=text.ToString();foreach(int page in new[]{1,7})foreach(var a in cached[page]){if(a.action.StartsWith("reassign"))a.gameObject.SetActive(match.players[int.Parse(a.action.Substring(8))].controller);if(a.action=="resume"||a.action=="start"){a.button.isInteractable=match.DevicesReady;a.GetComponent<UnityEngine.UI.Button>().interactable=match.DevicesReady;}}Focus();SelectPrimary();}
 void SelectPrimary(){if((Screen!=AirHockeyScreen.Join&&Screen!=AirHockeyScreen.Disconnect)||!match.DevicesReady||cached==null||EventSystem.current==null)return;foreach(var a in cached[(int)Screen])if(a.action==(Screen==AirHockeyScreen.Join?"start":"resume")){EventSystem.current.SetSelectedGameObject(a.gameObject);break;}}
 protected override void Update(){base.Update();if(!released&&Time.frameCount>gateFrame){bool neutral=!SportsDeviceInput.KeyHeld(Key.Enter)&&!SportsDeviceInput.KeyHeld(Key.Space)&&(Mouse.current==null||!Mouse.current.leftButton.isPressed&&!Mouse.current.leftButton.wasReleasedThisFrame);for(int i=0;i<2;i++)if(match.Ready(i))neutral&=match.Neutral(i);foreach(var pad in Gamepad.all)neutral&=!pad.buttonSouth.isPressed;if(neutral){released=true;SelectPrimary();}}Refresh();foreach(var pad in Gamepad.all)if(menuInput.Down(pad,8)&&Screen!=AirHockeyScreen.Play){Back();break;}if(Time.unscaledTime<nextHud)return;nextHud=Time.unscaledTime+.1f;if(presentation!=null){presentation.Refresh();return;}if(Screen==AirHockeyScreen.Play){scoreText.text="<color=#"+ColorUtility.ToHtmlStringRGB(match.players[0].color)+">"+match.players[0].name+"  "+match.rules.Score[0]+"</color>   :   <color=#"+ColorUtility.ToHtmlStringRGB(match.players[1].color)+">"+match.rules.Score[1]+"  "+match.players[1].name+"</color>";serveText.text="FIRST TO 7 • "+match.players[match.rules.Server].name+" serves • Each truck stays in its half";noticeText.text=match.rules.Phase==AirHockeyPhase.Countdown?match.Notice+"  "+Mathf.Max(1,Mathf.CeilToInt(match.rules.Timer)):match.Notice;}}
 public void Celebrate(bool winner){celebration?.Kill();resultTitle.localScale=Vector3.one;celebration=resultTitle.DOScale(winner?1.06f:1.02f,.18f).SetLoops(2,LoopType.Yoyo).SetUpdate(true);if(winner)foreach(var p in match.players)if(p.controller&&p==match.players[match.rules.Winner])feedback.Pulse(p.pad,.2f,.2f);}
 void OnDisable(){celebration?.Kill();}
}
}
